code.C:
#include <stdio.h>

int main() {
    long long a, b;
    if (scanf("%lld %lld", &a, &b) == 2) {
        long long q = 0;
        while (a >= b) {
            a -= b;
            q++;
        }
        printf("%lld\n", q);
    }
    return 0;
}

